; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 only when the library itself is built as a ROM (ntcRomAsm)

ntc_start:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 12: Input "How many passes (Return = 5)"; passes
			dw kw_printstrvar, str0
			dw kw_inputint, var_passes

			; main.bas 13: If passes < 1 Or passes > 100 Then passes = 5
			dw kw_scpltvl, var_passes, 1
			dw kw_ftov, tmp0
			dw kw_scpgtvl, var_passes, 100
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, if1_1
			dw kw_ltov, 5, var_passes
if1_1:

			; main.bas 14: Do
do2_t:

			; main.bas 15: Print
			dw kw_printnl

			; main.bas 16: Print "T = turbo, N = normal, X = exit"
			dw kw_printstrvar, str1
			dw kw_printnl

			; main.bas 17: Do : k = UCase$(Inkey$) : Frame : Loop Until (k = "T") Or (k = "N") Or (k = "X")
do3_t:
			dw kw_inkeys, stmp0
			dw kw_strucase, stmp0, stmp0
			dw kw_strcpy, var_k, stmp0
			dw kw_frame
			dw kw_strcmpeq, var_k, str2
			dw kw_ftov, tmp0
			dw kw_strcmpeq, var_k, str3
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_strcmpeq, var_k, str4
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, do3_t
do3_e:

			; main.bas 18: If k = "X" Then Exit Do
			dw kw_strcmpeq, var_k, str4
			dw kw_goto_iffalse_n, if4_1
			dw do2_e_go
if4_1:

			; main.bas 19: Print IIf(k = "T", "Turbo", "Normal"); ": "; passes; " passes..."
			dw kw_strcmpeq, var_k, str2
			dw kw_ftov, tmp0
			dw kw_goto_ifzero_n, tmp0, ch5_0
			dw kw_strcpy, stmp0, str5
			dw ch5_e_go
ch5_0:
			dw kw_strcpy, stmp0, str6
			dw ch5_e_go
ch5_1:
			dw kw_strcpy, stmp0, str7
ch5_e:
			dw kw_printstrvar, stmp0
			dw kw_printstrvar, str8
			dw kw_printint, var_passes
			dw kw_printstrvar, str9
			dw kw_printnl

			; main.bas 20: t0 = Ticks
			dw kw_ticks, tmp0
			dw kw_vtov, tmp0, var_t0

			; main.bas 21: If k = "T" Then
			dw kw_strcmpeq, var_k, str2
			dw kw_goto_iffalse_n, if6_1

			; main.bas 22: Turbo On
			dw kw_turbo_on

			; main.bas 23: RunPasses
			dw p_runpasses_c

			; main.bas 24: Turbo Off
			dw kw_turbo_off

			; main.bas 25: Else
			dw if6_e_go
if6_1:

			; main.bas 26: RunPasses
			dw p_runpasses_n_c

			; main.bas 27: End If
if6_e:

			; main.bas 28: t1 = Ticks
			dw kw_ticks, tmp0
			dw kw_vtov, tmp0, var_t1

			; main.bas 29: Print "Done - stop the stopwatch"
			dw kw_printstrvar, str10
			dw kw_printnl

			; main.bas 30: Print cnt; " primes below "; TOP
			dw kw_printint, var_cnt
			dw kw_printstrvar, str11
			dw kw_printnl

			; main.bas 31: If (k = "N") And (System.TicksPerSecond > 0) Then
			dw kw_strcmpeq, var_k, str3
			dw kw_ftov, tmp0
			dw kw_goto_ifzero_n, tmp0, if7_1

			; main.bas 32: Print "took "; t1 - t0; " ticks = "; (t1 - t0) \ System.TicksPerSecond; "."; ((t1 - t0) Mod System.TicksPerSecond) * 10 \ System.TicksPerSecond; " s"
			dw kw_subvv, var_t1, var_t0, tmp0
			dw kw_printstrvar, str12
			dw kw_printint, tmp0
			dw kw_subvv, var_t1, var_t0, tmp0
			dw kw_divvl, tmp0, 300, tmp0
			dw kw_printstrvar, str13
			dw kw_printint, tmp0
			dw kw_subvv, var_t1, var_t0, tmp0
			dw kw_modvl, tmp0, 300, tmp0
			dw kw_mulvl, tmp0, 10, tmp0
			dw kw_divvl, tmp0, 300, tmp0
			dw kw_printstrvar, str14
			dw kw_printint, tmp0
			dw kw_printstrvar, str15
			dw kw_printnl

			; main.bas 33: ElseIf k = "T" Then
			dw do2_t_go
if7_1:
			dw kw_strcmpeq, var_k, str2
			dw kw_goto_iffalse_n, do2_t

			; main.bas 34: Print "(turbo runs with interrupts off, so"
			dw kw_printstrvar, str16
			dw kw_printnl

			; main.bas 35: Print "time it with the stopwatch)"
			dw kw_printstrvar, str17
			dw kw_printnl

			; main.bas 36: End If
if7_2:
if7_e:

			; main.bas 37: Loop
			dw do2_t_go
do2_e:

			; main.bas 38: End
			dw kw_stop

; ============================================================
; sub runpasses (turbo mode)
; ============================================================

p_runpasses:

			; main.bas 41: Dim p As Integer

			; main.bas 42: For p = 1 To passes
			dw kw_ltov, 1, var_runpasses_p
			dw kw_vtov, var_passes, for8_l
			dw kw_forupv, var_runpasses_p, for8_l, for8_e
for8_t:

			; main.bas 43: Sieve
			dw p_sieve_c

			; main.bas 44: Next
			dw kw_next1v, var_runpasses_p, for8_l, for8_t
for8_e:
			dw p_runpasses_r

; ============================================================
; sub runpasses (normal mode)
; ============================================================

p_runpasses_n:

			; main.bas 41: Dim p As Integer

			; main.bas 42: For p = 1 To passes
			dw kw_ltov, 1, var_runpasses_p
			dw kw_vtov, var_passes, for9_l
			dw kw_forupv_n, var_runpasses_p, for9_l, for9_e
for9_t:

			; main.bas 43: Sieve
			dw p_sieve_n_c

			; main.bas 44: Next
			dw kw_next1v_n, var_runpasses_p, for9_l, for9_t
for9_e:
			dw p_runpasses_n_r

; ============================================================
; sub sieve (turbo mode)
; ============================================================

p_sieve:

			; main.bas 48: Dim i As Integer, j As Integer

			; main.bas 49: For i = 2 To TOP
			dw kw_ltov, 2, var_sieve_i
for10_t:

			; main.bas 50: f(i) = 1
			dw kw_aset8, arr_f, var_sieve_i, lit_1

			; main.bas 51: Next
			dw kw_next1l, var_sieve_i, 8000, for10_t
for10_e:

			; main.bas 52: cnt = 0
			dw kw_ztov, var_cnt

			; main.bas 53: For i = 2 To TOP
			dw kw_ltov, 2, var_sieve_i
for11_t:

			; main.bas 54: If f(i) = 1 Then
			dw kw_aget8, arr_f, var_sieve_i, tmp0
			dw kw_cpeqvl, tmp0, 1
			dw kw_goto_iffalse, if12_1

			; main.bas 55: cnt = cnt + 1
			dw kw_inc, var_cnt

			; main.bas 56: j = i + i
			dw kw_add, var_sieve_i, var_sieve_i, var_sieve_j

			; main.bas 57: Do While j <= TOP
do13_t:
			dw kw_scplevl, var_sieve_j, 8000
			dw kw_goto_iffalse, do13_e

			; main.bas 58: f(j) = 0
			dw kw_aset8, arr_f, var_sieve_j, lit_0

			; main.bas 59: j = j + i
			dw kw_add, var_sieve_j, var_sieve_i, var_sieve_j

			; main.bas 60: Loop
			dw do13_t_go
do13_e:

			; main.bas 61: End If
if12_1:

			; main.bas 62: Next
			dw kw_next1l, var_sieve_i, 8000, for11_t
for11_e:
			dw p_sieve_r

; ============================================================
; sub sieve (normal mode)
; ============================================================

p_sieve_n:

			; main.bas 48: Dim i As Integer, j As Integer

			; main.bas 49: For i = 2 To TOP
			dw kw_ltov, 2, var_sieve_i
for14_t:

			; main.bas 50: f(i) = 1
			dw kw_aset8, arr_f, var_sieve_i, lit_1

			; main.bas 51: Next
			dw kw_next1l_n, var_sieve_i, 8000, for14_t
for14_e:

			; main.bas 52: cnt = 0
			dw kw_ztov, var_cnt

			; main.bas 53: For i = 2 To TOP
			dw kw_ltov, 2, var_sieve_i
for15_t:

			; main.bas 54: If f(i) = 1 Then
			dw kw_aget8, arr_f, var_sieve_i, tmp0
			dw kw_cpeqvl, tmp0, 1
			dw kw_goto_iffalse_n, if16_1

			; main.bas 55: cnt = cnt + 1
			dw kw_inc, var_cnt

			; main.bas 56: j = i + i
			dw kw_add, var_sieve_i, var_sieve_i, var_sieve_j

			; main.bas 57: Do While j <= TOP
do17_t:
			dw kw_scplevl, var_sieve_j, 8000
			dw kw_goto_iffalse_n, do17_e

			; main.bas 58: f(j) = 0
			dw kw_aset8, arr_f, var_sieve_j, lit_0

			; main.bas 59: j = j + i
			dw kw_add, var_sieve_j, var_sieve_i, var_sieve_j

			; main.bas 60: Loop
			dw do17_t_go
do17_e:

			; main.bas 61: End If
if16_1:

			; main.bas 62: Next
			dw kw_next1l_n, var_sieve_i, 8000, for15_t
for15_e:
			dw p_sieve_n_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do2_e_go:			ld sp, do2_e
			jp ntc_xn
ch5_e_go:			ld sp, ch5_e
			jp ntc_xn
if6_e_go:			ld sp, if6_e
			jp ntc_xn
do2_t_go:			ld sp, do2_t
			jp ntc_xn
do13_t_go:			ld sp, do13_t
			ret
do17_t_go:			ld sp, do17_t
			jp ntc_xn

p_runpasses_c:		; call runpasses (turbo)
			ld hl, 0
			ld (var_runpasses_p), hl
			ld (p_runpasses_rs), sp
			ld sp, p_runpasses
			ret
p_runpasses_r:		; end of runpasses
			ld sp, (p_runpasses_rs)
			ret
p_runpasses_n_c:		; call runpasses (normal)
			ld hl, 0
			ld (var_runpasses_p), hl
			ld (p_runpasses_rs), sp
			ld sp, p_runpasses_n
			jp ntc_xn
p_runpasses_n_r:		; end of runpasses
			ld sp, (p_runpasses_rs)
			jp ntc_xn
p_sieve_c:		; call sieve (turbo)
			ld hl, 0
			ld (var_sieve_i), hl
			ld hl, 0
			ld (var_sieve_j), hl
			ld (p_sieve_rs), sp
			ld sp, p_sieve
			ret
p_sieve_r:		; end of sieve
			ld sp, (p_sieve_rs)
			ret
p_sieve_n_c:		; call sieve (normal)
			ld hl, 0
			ld (var_sieve_i), hl
			ld hl, 0
			ld (var_sieve_j), hl
			ld (p_sieve_rs), sp
			ld sp, p_sieve_n
			jp ntc_xn
p_sieve_n_r:		; end of sieve
			ld sp, (p_sieve_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_passes:			dw 0
			db 40			; capacity
var_k:			ds 41
var_t0:			dw 0
var_t1:			dw 0
var_cnt:			dw 0
p_runpasses_rs:			dw 0
var_runpasses_p:			dw 0
for8_l:			dw 0
for9_l:			dw 0
p_sieve_rs:			dw 0
var_sieve_i:			dw 0
var_sieve_j:			dw 0
tmp0:			dw 0
tmp1:			dw 0
			db 255			; capacity
stmp0:			ds 256

; numbers passed by address (read only)
lit_1:			dw 1
lit_0:			dw 0

; ============================================================
; Strings
; ============================================================

str0:			db "How many passes (Return = 5)? ", 0
str1:			db "T = turbo, N = normal, X = exit", 0
str2:			db "T", 0
str3:			db "N", 0
str4:			db "X", 0
str5:			db "Turbo", 0
str6:			db "Normal", 0
str7:			db 0
str8:			db ": ", 0
str9:			db " passes...", 0
str10:			db "Done - stop the stopwatch", 0
str11:			db " primes below 8000", 0
str12:			db "took ", 0
str13:			db " ticks = ", 0
str14:			db ".", 0
str15:			db " s", 0
str16:			db "(turbo runs with interrupts off, so", 0
str17:			db "time it with the stopwatch)", 0

; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCFW (NTCFW.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_turbo_on:	jp 5
kw_turbo_off:	jp 7
kw_goto_iffalse:	jp 10
kw_goto_iffalse_n:	jp 11
kw_goto_ifzero_n:	jp 15
kw_forupv:	jp 24
kw_forupv_n:	jp 25
kw_next1l:	jp 30
kw_next1l_n:	jp 31
kw_next1v:	jp 32
kw_next1v_n:	jp 33
kw_ltov:		jp 47
kw_vtov:		jp 48
kw_ztov:		jp 49
kw_ftov:		jp 50
kw_inc:		jp 51
kw_add:		jp 53
kw_subvv:	jp 55
kw_mulvl:	jp 61
kw_divvl:	jp 64
kw_modvl:	jp 67
kw_orvv:		jp 74
kw_scpltvl:	jp 80
kw_scplevl:	jp 82
kw_scpgtvl:	jp 84
kw_cpeqvl:	jp 96
kw_aget8:	jp 113
kw_aset8:	jp 114
kw_strcpy:	jp 122
kw_strcmpeq:	jp 126
kw_printstrvar:	jp 129
kw_printint:	jp 131
kw_printnl:	jp 138
kw_inputint:	jp 142
kw_inkeys:	jp 145
kw_frame:	jp 152
kw_ticks:	jp 154
kw_strucase:	jp 180
kw_bssinit:	jp 288
NTC_RJ_N	equ 41		; entries
ntc_csp	equ #8800		; ROM data
ntc_nmode	equ #8807		; ROM data
ntc_v_free	equ #895E		; ROM data
ntc_v_romen	equ #8964		; ROM data
ntc_v_romold	equ #8966		; ROM data
ntc_v_stamp	equ #8962		; ROM data
ntc_v_start	equ #8960		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; the start: find the ROM in slots 0 - 31, have it patch the jump block. NC = ready;
; C = not there / too old (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, c				; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot; C: DE = a number it hasn't got
			jr c, ntc_rj_lacks
			ld hl, ntc_free
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld hl, ntc_rj_tlk
			or a
			sbc hl, de			; (DE: past the message shown)
			jr nz, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)
ntc_rj_num:		dw 0
ntc_rj_sig:		db "NTC", 1, "CPCFW", 0	; the ROM's NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPCFW (NTCFW.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPCFW too old: no routine #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
arr_f		equ ntc_bss + 0		; 8001 bytes
ntc_bss_size	equ 8001
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			SAVEAMSDOS "SIEVETIM.BIN", ntc_start, ntc_end - ntc_start, ntc_start
